{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PUSHBACK",
      "evidence": "Seek a higher general cap, calibrated to diligence and available recovery."
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "Seek lower thresholds and a tipping basket."
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "Seek a longer general warranty period, for example 24–36 months as an opening position."
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Separate fundamental regime: seek at least a purchase-price cap and a materially longer claim period, with fraud separately carved out."
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Preserve fraud, fraudulent concealment and rights that cannot lawfully be excluded"
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Require fair disclosure with sufficient detail to identify the matter’s nature and scope, preferably against relevant warranties."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Delete the exclusion."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Require an express Buyer-waivable completion condition: valid, effective change-control consent and satisfaction of its associated conditions, without materially adverse amendments."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Require repayment and effective releases at Completion through an agreed simultaneous settlement process."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Allocate the economic cost to Seller expressly, including applicable superannuation, payroll tax and other on-costs."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "A specific indemnity covering losses from pre-completion non-payment or defective title, including reasonable defence, remediation and replacement costs—not merely the unpaid invoice."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "A specific indemnity for the pre-completion incident and associated reasonable investigation, remediation, notification and third-party costs, to the extent legally recoverable."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PUSHBACK",
      "evidence": "Require Buyer consent to material new commitments before Completion, aggregated across related transactions."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "The SPA must expressly establish that specific indemnities and other negotiated exceptions prevail over inconsistent all-claims limitations."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "The register is useful evidence, but not complete verification of valid ownership and an unencumbered transfer of all issued shares."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Require a separate pre-completion tax indemnity/covenant, tailored exclusions and a period linked to relevant assessment periods plus a buffer."
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": false
}

